export const isFragrance=p=>p?.type==='perfume'&&p.fragranceProfile?.reviewed===true;
const ease=t=>{const x=Math.max(0,Math.min(1,t));return x*x*x*(x*(x*6-15)+10);};
// A closed bottle is lifted, read, gently turned and lowered. No spray or scent simulation.
export function fragranceHold(profile,time,reduced=false,rest){
 const t=Number.isFinite(time)?Math.max(0,time):0,reach=reduced?1:ease(t/.8)*(1-ease((t-3.5)/.9)),turn=reduced?0:t<1?0:t<1.9?.3*ease((t-1)/.9):t<2.4?.3:t<3.3?.3*(1-ease((t-2.4)/.9)):0;
 const scale=.4,r=profile.radius*scale,grips=[{x:-r-.05,y:profile.bodyHeight*scale*.36,z:0},{x:r+.05,y:profile.bodyHeight*scale*.64,z:0}],baseY=28,z=10.5,co=Math.cos(turn),si=Math.sin(turn);
 const hands=grips.map((h,i)=>{const a=rest?.[i]||{x:(i?1:-1)*10,y:22,z:1.5},b={x:h.x*co,y:baseY+h.y,z:z-h.x*si};return {x:a.x+(b.x-a.x)*reach,y:a.y+(b.y-a.y)*reach,z:a.z+(b.z-a.z)*reach};});
 // The bottle follows the same lift and lower as the two hands.
 return {reach,turn,hands,baseY:(hands[0].y+hands[1].y)/2-profile.bodyHeight*scale*.5,z:(hands[0].z+hands[1].z)/2,visible:reduced||reach>.02};
}
export function fragranceFactsHTML(p,esc){if(!isFragrance(p))return '';const a=p.fragranceProfile;return `<section class="fragrance-facts frame-facts"><h4>Selected fragrance reference</h4><p>${esc(p.brand)} · SKU <strong>${esc(p.referenceSKU)}</strong> · ${esc(p.sizes[0])} · ${esc(a.concentration)}.</p><p>Published fragrance notes: ${a.notes.map(esc).join(' · ')}. These describe the merchant’s reference, not an ingredient list or a scent produced by the game.</p><p>${esc(p.sourceOfferNote)}</p><details><summary>Bottle & photograph notes</summary><p>${esc(a.photoBasis)}</p><p>The original glass model uses adapted proportions, a plain label and simplified gold joinery. Bottle dimensions are not published here. Inspection keeps the cap on; refilling, spraying, scent, longevity and skin suitability are not simulated.</p></details></section>`;}
export function fragranceNotebookHTML(st,esc){return `<div class="modal-body fragrance-notebook"><span class="eyebrow">SOURCE NOTEBOOK · FREE TO READ</span><h3>Three references, side by side.</h3><p>Use the published notes to compare these exact formats. Opening a card is free and pauses time. A bottle inspection uses its displayed six game minutes.</p><div class="fragrance-note-grid">${st.products.filter(isFragrance).map(p=>`<article><h3>${esc(p.name)}</h3><p>${esc(p.sizes[0])} · ${esc(p.fragranceProfile.concentration)}</p><ul>${p.fragranceProfile.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul><button class="button secondary wide" data-action="detail" data-id="${esc(p.id)}">View bottle & source</button></article>`).join('')}</div><p class="hint">These are source descriptions, not a fragrance recommendation. Shop availability and the game’s stock are simulated.</p><button class="button secondary" data-action="collection-open">Back to the collection desk</button></div>`;}
